/* NEXZO Academic mastery quiz v238. Topic-specific, deterministic and UID-scoped. */
(()=>{
  if(document.body?.dataset.page!=='academics')return;
  const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
  const uid=()=>window.NEXZODataService?.getUser?.()?.uid||localStorage.getItem('nexzo_canonical_cache_owner')||'guest';
  const localKey=()=>`nexzo_academic_quiz_v3:${uid()}`;let results={};
  try{results=JSON.parse(localStorage.getItem(localKey())||'{}')||{}}catch{results={}}
  let remoteState=null;
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const stable=text=>{let h=2166136261;for(const c of String(text)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return Math.abs(h)};
  const key=(subject,index)=>`${subject}:${index}`;
  async function hydrate(){if(uid()==='guest'||!window.NEXZOBackendStore?.getState)return;try{const r=await window.NEXZOBackendStore.getState('academics');remoteState=r?.data||{};if(remoteState.quizResults){results={...results,...remoteState.quizResults};localStorage.setItem(localKey(),JSON.stringify(results));install()}}catch{}}
  async function persist(){localStorage.setItem(localKey(),JSON.stringify(results));if(uid()==='guest'||!window.NEXZOBackendStore?.putState)return;try{const current=remoteState||((await window.NEXZOBackendStore.getState('academics'))?.data||{});remoteState={...current,quizResults:results,updatedAtMs:Date.now()};await window.NEXZOBackendStore.putState('academics',remoteState)}catch{window.NEXZOShell?.toast?.('Quiz saved on this device; cloud sync is pending.','info')}}
  function question(topic,subject,index){const prompts=[`Which statement is most accurate about ${topic} in ${subject}?`,`A student is revising ${topic}. Which action demonstrates correct understanding?`,`In an exam question about ${topic}, which point should be included?`,`Which example best applies the idea of ${topic}?`,`What is the primary purpose of studying ${topic} in ${subject}?`];const correct=`The answer must use the defining idea and terminology of ${topic}.`;const wrong=[`It can be answered without referring to ${topic}.`,`It is unrelated to ${subject} and its syllabus.`,`It replaces every other concept in the unit.`];const options=[correct,...wrong],shift=stable(`${subject}:${topic}:${index}`)%4;return{q:prompts[index%prompts.length],correct,options:[...options.slice(shift),...options.slice(0,shift)]}}
  function unitTopics(unit){return $$('.nx-topic-row>span:first-child',unit).map(x=>x.textContent.trim()).filter(Boolean)}
  function isPassed(i,subject){return Number(results[key(subject,i)]?.score||0)>=4}
  function ensureQuizButton(unit,i,subject){if(i>0&&!isPassed(i-1,subject)){unit.classList.add('nx-unit-locked');unit.querySelector('.nx-unit-body')?.setAttribute('hidden','')}else unit.classList.remove('nx-unit-locked');let b=unit.querySelector('[data-v238-quiz]');if(!b){b=document.createElement('button');b.type='button';b.className='nx-unit-quiz-btn';b.dataset.v238Quiz=i;unit.querySelector('.nx-unit-body')?.append(b)}const saved=results[key(subject,i)];b.textContent=saved?`✓ Quiz result · ${saved.score}/10`:'Take 10-question topic quiz'}
  function install(){const subject=String($('.nx-workspace-head h2')?.textContent||'Academics').trim();$$('.nx-unit').forEach((u,i)=>ensureQuizButton(u,i,subject))}
  function showQuiz(unit,index,subject){const topics=unitTopics(unit);if(!topics.length)return;const questions=Array.from({length:10},(_,n)=>question(topics[n%topics.length],subject,n));let n=0,score=0,answered=false,modal=$('#nxV238Quiz');if(!modal){modal=document.createElement('div');modal.id='nxV238Quiz';modal.className='nx-unit-quiz-modal';document.body.append(modal)}const draw=()=>{answered=false;const item=questions[n];modal.hidden=false;modal.innerHTML=`<div class="nx-unit-quiz-card"><button type="button" data-v238-close>×</button><span>TOPIC QUIZ · ${n+1}/10</span><h2>${esc(item.q)}</h2><p class="nx-quiz-topic">Topic: ${esc(topics[n%topics.length])}</p><div class="nx-v237-options">${item.options.map((x,i)=>`<button type="button" data-v238-answer="${i}">${esc(x)}</button>`).join('')}</div><small>Minimum 4/10 unlocks the next unit.</small></div>`;$$('[data-v238-answer]',modal).forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const correct=Number(b.dataset.v238Answer)===item.options.indexOf(item.correct);if(correct)score++;$$('[data-v238-answer]',modal).forEach(x=>x.disabled=true);const note=document.createElement('p');note.textContent=correct?`Correct. ${item.correct}`:`Incorrect. Correct answer: ${item.correct}`;modal.querySelector('.nx-unit-quiz-card').append(note);setTimeout(()=>{n++;n<10?draw():finish()},500)})};const finish=async()=>{const k=key(subject,index),result={score,attempts:(results[k]?.attempts||0)+1,passed:score>=4,completedAtMs:Date.now()};results[k]=result;await persist();modal.innerHTML=`<div class="nx-unit-quiz-card"><h2>${result.passed?'Unit unlocked ✓':'Revise and retry'}</h2><p>Your score: <b>${score}/10</b></p><button type="button" data-v238-close>Continue</button></div>`;install();window.dispatchEvent(new CustomEvent('nexzo:academics-quiz',{detail:{uid:uid(),subject,unit:index,score,passed:result.passed,attempts:result.attempts}}))};draw()}
  document.addEventListener('click',e=>{const q=e.target.closest('[data-v238-quiz]');if(q){e.preventDefault();e.stopPropagation();const subject=String($('.nx-workspace-head h2')?.textContent||'Academics').trim();showQuiz(q.closest('.nx-unit'),Number(q.dataset.v238Quiz),subject);return}const locked=e.target.closest('.nx-unit-locked');if(locked&&!e.target.closest('[data-v238-quiz]')){e.preventDefault();e.stopPropagation();window.NEXZOShell?.toast?.('Pass the previous topic quiz first (minimum 4/10).','info')}if(e.target.closest('[data-v238-close]'))$('#nxV238Quiz')?.setAttribute('hidden','')});new MutationObserver(install).observe(document.body,{childList:true,subtree:true});setTimeout(install,700);hydrate();
})();
